using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace BuyBidBlow.PlayerUISandbox.Editor {
[InitializeOnLoad] public static class ExchangeControlsPatch {
static ExchangeControlsPatch(){EditorApplication.update+=()=>{if(!File.Exists("Library/ExchangeControls.request")||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlaying)return;bool relocate=File.ReadAllText("Library/ExchangeControls.request").Trim()=="exchange";File.Delete("Library/ExchangeControls.request");try{Apply(relocate);File.WriteAllText("Library/ExchangeControls.result","PASS");}catch(Exception e){File.WriteAllText("Library/ExchangeControls.result",e.ToString());Debug.LogException(e);}};}
public static void Apply(bool relocate=false){var scene=SceneManager.GetSceneByPath("Assets/Project/Dev/Sandbox/Interface/PlayerUI/SC_PlayerUI.unity");if(!scene.isLoaded)scene=EditorSceneManager.OpenScene("Assets/Project/Dev/Sandbox/Interface/PlayerUI/SC_PlayerUI.unity",OpenSceneMode.Single);var roots=scene.GetRootGameObjects();var c=roots.SelectMany(g=>g.GetComponentsInChildren<PlayerUIController>(true)).Single();
if(relocate&&!roots.Any(g=>g.name=="Exchange - Opposite Wall")){var group=new GameObject("Exchange - Opposite Wall");var exchange=roots.Single(g=>g.name=="Exchange - Editable Set Dressing");exchange.transform.SetParent(group.transform,true);var board=roots.Single(g=>g.name=="Exchange Prices - World Space Editable");board.transform.SetParent(group.transform,true);foreach(var t in roots.SelectMany(g=>g.GetComponentsInChildren<UIInteractionTarget>(true)).Where(t=>t.kind!=UIInteractionTarget.Kind.AuctionSeat).ToArray())t.transform.SetParent(group.transform,true);var wolves=roots.FirstOrDefault(g=>g.name=="Wolf Characters - Static Examples");if(wolves)foreach(Transform wolf in wolves.transform.Cast<Transform>().ToArray())if(wolf.position.z < -2)wolf.SetParent(group.transform,true);group.transform.rotation=Quaternion.Euler(0,180,0);}
c.body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;c.body.interpolation=RigidbodyInterpolation.Interpolate;
var path="Assets/Project/Dev/Sandbox/Interface/PlayerUI/Prefabs/Player_Capsule_NoFriction.asset";var mat=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(path);if(!mat){mat=new PhysicsMaterial("Player Capsule - No Friction");AssetDatabase.CreateAsset(mat,path);}mat.dynamicFriction=0;mat.staticFriction=0;mat.frictionCombine=PhysicsMaterialCombine.Minimum;c.GetComponent<CapsuleCollider>().sharedMaterial=mat;
c.transform.rotation=Quaternion.Euler(0,relocate||scene.GetRootGameObjects().Any(g=>g.name=="Exchange - Opposite Wall")?0:180,0);PrefabUtility.SaveAsPrefabAsset(c.gameObject,"Assets/Project/Dev/Sandbox/Interface/PlayerUI/Prefabs/PF_PlayerUIRig.prefab");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText("Assets/Project/Dev/Sandbox/Interface/PlayerUI/ControlsVerification.txt","Applied: exchange/counters/board/trade hitboxes and nearby static wolves rotated 180 degrees around hall center; player faces new exchange. Stable optional movement enabled only on this rig: normalized input, acceleration, normal-filtered foot sphere cast, edge-triggered buffered jump/coyote time, fixed-step yaw, sensitivity .15 deg/pixel, no-friction capsule and continuous collision. UI close preserves camera pitch. Original Move & Trade scene unchanged.");}
}
}